local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[6503] = { title = "Die Kundschafter von Ashenvale", description = "Es wurde uns berichtet, dass Kundschafter Ashenvales vor nicht langer Zeit den Außenposten der Silverwing verlassen haben und sich jetzt in der Nähe unserer Territorien im Wald herumtreiben. Wir möchten nicht, dass sie unsere Verteidigung ausspionieren!\n\nSchleicht durch den Wald südlich unseres Postens und östlich des Außenpostens der Allianz von Silverwing. Findet und tötet die Kundschafter und kehrt dann zu mir zurück.", objectives = "Tötet 9 Kundschafter von Ashenvale und kehrt dann zu Kuray'bin im Splintertreeaußenposten zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6504] = { title = "Die verlorenen Seiten", description = "Ich habe gerade diesen Schredder in Ratchet abgeholt und war auf dem Heimweg ins Holzfällerlager der Warsong, in dem ich eigentlich Dienst verrichten sollte. Man hat mir eine Anleitung zur Bedienung des Schredders mitgegeben, aber auf dem Rückweg hat ein starker Windstoß sie mir aus den Händen geweht. Die Seiten sind überallhin geflogen und mir blieb nur noch der Einband.\n\nDie Seiten könnten mittlerweile überall sein, nehme ich an ... aber ich weiß nicht, wie ich den Schredder ohne sie benutzen soll! Würdet Ihr sie für mich suchen?", objectives = "Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6521] = { title = "Eine unheilige Allianz", description = "Malcin behauptet, dass er sich abseits der Hügel von Razorfen aufhalte. Dieser Botschafter muss getötet werden - seine Mission in den Augen des Lichkönigs ein glatter Fehlschlag sein.\n\nSeine Anwesenheit dort erklärt vieles von dem, was wir über diese Gegend herausgefunden haben - einige der Stacheleber sind beängstigend stark geworden und zeigen erste Symptome der Seuche. Das muss in der Tat ein Anzeichen dafür sein, dass sie irgendeine Übereinkunft getroffen haben.\n\nSucht Malcin und tötet ihn, $N. Kommt zurück, wenn Ihr das erledigt habt.", objectives = "Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6522] = { title = "Eine unheilige Allianz", description = "Milady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf weiteres abseits der Hügel von Razorfen aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", objectives = "Bringt die kleine Rolle zu Varimathras nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6523] = { title = "Schützt Kaya", description = "Habt Dank für meine Rettung! Wir müssen schnell fort von hier, ehe man bemerkt, dass ich frei bin. Bitte begleitet mich zum Camp Aparaje. Von dort aus kenne ich den Weg.\n\nMein Vater Makaba Flathoof wird unbedingt wissen wollen, dass ich in Sicherheit bin.", objectives = "Begleitet Kaya Flathoof zum Camp Aparaje und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6541] = { title = "Meldung bei Kadrak", description = "Seid Ihr jemals im Norden von Ashenvale gewesen? Die Horde hat dort vor kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Ashenvalekampagne und kann Euch weitere Befehle geben.", objectives = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6542] = { title = "Meldung bei Kadrak", description = "Seid Ihr jemals im Norden von Ashenvale gewesen? Die Horde hat dort vor kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Ashenvalekampagne und kann Euch weitere Befehle geben.", objectives = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6543] = { title = "Die Warsongberichte", description = "Ich habe kürzlich ein paar Späher nach Ashenvale entsandt und brauche jetzt einen Läufer, der ihnen neue Befehle übermittelt und mir einen Bericht über deren Entdeckungen bringt.\n\nEuer erster Halt sollte der Zoram'gar-Außenposten an der Küste Richtung Westen sein. Dort solltet Ihr den ersten Läufer finden. Ihr müsst weiterhin beim Splintertreeposten im Norden und an der Straße nach Osten, die nach Azshara führt, Halt machen. Dort findet Ihr einen Späher und einen Vorreiter.\n\nErstattet allen Bericht und lasst Euch von ihnen über ihre Entdeckungen informieren.", objectives = "Bringt die Warsongberichte dem Warsongspäher, dem Warsongläufer und der Warsongvorhut. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6544] = { title = "Toreks Angriff", description = "He! $C! Kommt mal her!\n\nMeine Räuber und ich wollten gerade den Außenposten der Silverwing im Westen angreifen. Unser Ziel ist der dortige Anführer, Duriel Moonfire. Späher berichten, dass der Außenposten durch Schildwachen und Krieger stark verteidigt wird. Das wird ein ruhmreicher Kampf!\n\nWollt Ihr an dem Ruhm teilhaben und uns helfen, $N? Falls ja, könnt Ihr meinem Vorgesetzten Ertog Ragetusk in Splintertree später davon berichten.\n\nWas meint Ihr? Seid Ihr dabei?", objectives = "Eskortiert Torek bei seinem Angriff auf den Außenposten der Silverwing und Duriel Moonfire. Erstattet dann Ertog Ragetusk im Splintertreeposten Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6545] = { title = "Warsongläufer-Update", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6546] = { title = "Warsongvorhut-Update", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6547] = { title = "Warsongspäher-Update", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6548] = { title = "Rächt mein Dorf", description = "Der Grimmtotemklan hat mein Dorf überfallen und fast alle getötet. Ich habe so viele ich konnte niedergestreckt, bin aber nur um Haaresbreite lebend entkommen.\n\nJetzt wünsche ich mir nichts mehr, als noch mehr von ihnen tot zu sehen, $n. Ihr findet sie gleich westlich von hier.", objectives = "Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6561] = { title = "Blackfathom-Schurkerei", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Bashana in Thunder Bluff seinen Kopf, $N.", objectives = "Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6562] = { title = "Ärger in der Tiefe", description = "Je'neu Sancrea braucht Hilfe. Er befindet sich im Zoram'gar-Außenposten in Ashenvale. Der Nachtelfenwald liegt im Norden des Steinkrallengebirges. Ihr erreicht ihn, indem Ihr über die Scherwindklippe oder nördlich durchs Brachland reist. Der Zoramstrand liegt weit im Westen des Waldes. Seid vorsichtig, $N. Dort gibt es Mächte, denen Eure Anwesenheit nicht gefallen wird.", objectives = "Sprecht in Ashenvale mit Je'neu Sancrea.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6563] = { title = "Die Essenz von Aku'mai", description = "Im Eingangsbereich des Tunnels der Blacktfathom-Tiefe findet man überall an den Höhlenwänden große Saphiransammlungen. Kürzlich ist aufgefallen, dass die Naga diese Kristalle abbauen. Bis wir herausgefunden haben, warum sie das tun, sollten wir die Naga einstweilen davon abhalten. Die Kristalle besitzen große Elementarkraft und wenn sie unangemessen eingesetzt werden, könnte man daraus eine mächtige arkane Komponente herstellen.\n\nWerdet Ihr mir helfen, $N? Die Blackfathom-Tiefe liegt am Zoramstrand nördlich unseres Außenpostens.", objectives = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6564] = { title = "Treue zu den Alten Göttern", description = "Die zerknitterte Notiz trägt eine kaum leserliche Handschrift:\n\n\"Ja, sagt allen Priesterinnen, dass sie mir die Kristalle bringen sollen. Die Wasserelementare sind stark in ihnen und sie werden unseren Aquamanten bei ihren Beschwörungen ungemein dienlich sein.\n\nIndem wir die Kraft dieser Kristalle beherrschen, beschwichtigen wir Aku'mai. Eines Tages werden wir genug Macht haben, um Aku'mai zu uns zurückzuholen. Dann wird die Welt wieder zur Ära ihrer einstigen Größe zurückkehren! Eine Ära, in der die Alten Götter herrschen!\"", objectives = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6565] = { title = "Treue zu den Alten Göttern", description = "Dieser Anhänger der Twilight-Hammer darf seinen Plan nicht in die Tat umsetzen. Die Twilight-Hammer verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, $N. Ich kann mich leider nicht selbst darum kümmern ... ich bin zu schwach.\n\nGeht zur Blackfathom-Tiefe, findet ihn und tötet ihn. Kommt zu mir nach Zoram'gar zurück, wenn Ihr es geschafft habt.", objectives = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6566] = { title = "Was der Wind erzählt", description = "Schön, Euch wiederzusehen, $n. Der Wind führt Kunde aus den Östlichen Königreichen mit sich.\n\nSetzt Euch und lauscht.", objectives = "Hört Thrall zu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6567] = { title = "Der Champion der Horde", description = "Ich habe Kunde von einem meiner Helden erhalten, dass es einen Weg zum Hort des Großdrachen geben könnte. Ihr müsst ihn suchen.\n\nRexxar streift durch die wüste Einöde von Desolace, immer auf Reisen zwischen dem Steinkrallengebirge und Feralas. Er erwartet Euch.", objectives = "Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6568] = { title = "Nachricht von Rexxar", description = "Was wisst Ihr über Illusionen, $N? Denn wisset, Ihr müsst eine Illusion erschaffen, um die Verteidigungslinien des schwarzen Drachenschwarms zu umgehen.\n\nIch kenne jemanden, der vielleicht bereit ist, Euch bei Eurem Täuschungsmanöver zu helfen. Sie hat unsereins in der Vergangenheit geholfen, wenn sie ein Unterfangen für würdig erachtete.\n\nIn den Westlichen Pestländern findet Ihr Myranda die Vettel, eine Meisterin der Illusionen... und eine Verbannte der Lordaeron-Allianz. Reist dorthin und nehmt diese Nachricht mit.", objectives = "Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6569] = { title = "Oculus-Illusionen", description = "Ihr möchtet also einer vom schwarzen Drachenschwarm werden, was, $R?\n\nDie Erschaffung einer Illusion, wie Ihr sie wünscht, ist eine Kleinigkeit, aber die für den Zauber erforderlichen Komponenten sind ziemlich schwierig zu beschaffen. Rexxar und der Kriegshäuptling haben Euch mit dieser Mission betraut, also muss Myranda wohl annehmen, dass Ihr fähig dazu seid.\n\nReist zur oberen Zitadelle der Blackrockspitze und tötet genug Mitglieder der schwarzen Drachenbrut, um eine Eurer Taschen mit deren Augen zu füllen.\n\nKehrt zu Myranda zurück, wenn Ihr genügend von dem Reagenz gesammelt habt.", objectives = "Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6570] = { title = "Aschenschwinge", description = "Ich habe dieses Medaillon mit der Magie versehen, die notwendig ist, um eine Illusion zu erschaffen und sie innerhalb der Einfriedung des Höhlenbaus von Aschenschwinge aufrechtzuerhalten.\n\nAschenschwinge ist ein uralter Drache, ein alter Torhüter Nefarians, der die schwere Bürde auf seinen Schultern trägt, jene der Drachenbrut auf die Probe zu stellen, die in den Rang einer Elitewache Onyxias aufsteigen wollen.\n\nReist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr dort seid, legt Ihr das Amulett an und folgt Eurem Schicksal, wo immer es Euch auch hinführen mag!", objectives = "Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6571] = { title = "Warsongnachschub", description = "Uns hier im Holzfällerlager der Warsong gehen langsam einige Dinge aus!\n\nUnsere Lieferung Sägeblätter liegt bei Pixel im Splintertreeposten. Jemand muss auch nach Booty Bay reisen, um eine Kiste mit Äxten bei Werftmeister Lozgil abzuholen.\n\nBei unserer Öl- und Seillieferung sieht es jedoch schon schwieriger aus. Die Furbolgs haben die Seile geraubt und die Satyrn haben das Öl abgefangen und nutzen es jetzt für abscheuliche Rituale in Night Run und Satyrnaar!\n\nIch komme in große Schwierigkeiten, wenn ich die Sachen nicht bald ausliefere... könnt Ihr mir helfen?", objectives = "Tragt den Warsongnachschub zusammen: Warsongsägeblätter, Holzfäller-Seil, Warsongöl und die Warsongaxtlieferung für Locke Okarr im Splintertreeposten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6581] = { title = "Warsongsägeblätter", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6582] = { title = "Die Prüfung der Schädel, Scryer", description = "Wir alle sind Kinder der Deathwing, Welpe. Wir müssen die Herrschaft über die niederen Aspekte durchsetzen.\n\nWenn Ihr wirklich eines Aufstiegs würdig seid, werden die Geringeren des Drachenschwarms vor Euch niedersinken.\n\nFindet deren Champions und vernichtet sie im Namen unseres Vaters!\n\nBegebt Euch nach Winterspring und spürt den mächtigen Blaudrachen Scryer auf. Zerschmettert ihn und alle anderen des blauen Drachenschwarms, die sich Euch in den Weg stellen. Entreißt ihm seinen Schädel und bringt ihn mir.", objectives = "Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.\n\nIhr wisst, dass Scryer in Winterspring zu finden ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6583] = { title = "Die Prüfung der Schädel, Somnus", description = "Genau wie unser Vater die Aspekte zerschmettert, müssen wir danach trachten, Chaos und Zerstörung unter ihren Kindern anzurichten.\n\nIhr müsst Eure Leistungsfähigkeit im Kampf gegen die schlaflosen Träumer auf die Probe stellen: die Kinder des Gründrachenschwarms.\n\nBegebt Euch zu den Sümpfen des Elends und spürt Somnus auf, den Drachenchampion des Gründrachenschwarms. Lasst Eurem Hass freien Lauf und bezwingt das Insekt ... Kommt mit seinem Schädel zu mir zurück ...", objectives = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6584] = { title = "Die Prüfung der Schädel, Chronalis", description = "Die Zeitbehüter, Kinder Nozdormusss - Lord der Jahrhunderte...\n\nEs sind derer drei, die die Höhlen der Zeit bewachen, aber nur einer, an dem der schwarze Drachenschwarm interessiert ist: Chronalisss, der Zeitverschieber, bevorzugter Drachling Nozdormusss.\n\nBesssiegt diesssen Champion, denn das wäre ein Schlag, der sssogar den stoischen Sand der Zzzeit erschüttern würde. Kehrt mit seinem Schädel zu mir zzzurück.", objectives = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6585] = { title = "Die Prüfung der Schädel, Axtroz", description = "Es war in den Bergen von Grim Batol, wo unser Vater gegen die vereinte Macht der Aspekte wütete. Die feige Tat des Verräters Alexstrasza verschaffte den übrigen Aspekten genug Zeit, um dem Zorn des Vaters zu entkommen.\n\nWasss für ein schändlicher Akt ...\n\nDer Rotdrachenschwarm bewacht heute Grim Batol und ihr Lieutenant Axtroz muss vernichtet werden. Bringt mir Axtroz' Schädel. Für den Vater, Welpe!", objectives = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6601] = { title = "Aufstieg...", description = "Ein Medaillon, aus den Schädeln Eurer Feinde gefertigt. Ihr kennt dieses Medaillon, nicht wahr? Zweifellos habt Ihr gesehen, wie Eure Ältesten es trugen.\n\nNehmt es, Welpe. Begebt Euch zur Spitze zurück und zeigt es General Drakkisath. Der General wird das Medaillon mit der letzten Verzauberung versehen und das Schmuckstück auf Euren Geist abstimmen.\n\nIhr werdet das fertige Medaillon als Ehrenabzeichen tragen, als Symbol für Euren Aufstieg in unsere am höchsten geschätzten Reihen: Wächter der Brutmutter.\n\nGeht!", objectives = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6602] = { title = "Blut des schwarzen Großdrachen-Helden", description = "Ihr werdet dem General einen Besuch abstatten, jawohl, aber nicht als einer des schwarzen Drachenschwarms.\n\nWisst Ihr, Zeremonie ist für den schwarzen Drachenschwarm nur ein anderer Begriff für Aderlass.\n\nDas ruhende Amulett benötigt nur das Blut des Generals, um wieder aktiv zu sein. Das ist einer ihrer primitiven, ausfallsicheren Mechanismen.\n\nKehrt zur Blackrockspitze zurück und vernichtet Drakkisath. Bringt sein Blut hierher zurück, dann aktiviere ich den Schlüssel zu Onyxias Hort.", objectives = "Begebt Euch zur Blackrockspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rexxar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6603] = { title = "Probleme in Winterspring", description = "In Winterspring gibt es Probleme!\n\nSicher, ich habe einige Zeit da draußen in der Wildnis zugebracht und weiß um diese Dinge... Es macht mich immer ganz stolz, das zu sagen. Für mich waren die Stunden, die ich dort draußen in den Hügeln verbrachte, etwas ganz Besonderes. Es hilft einem, blitzschnelle Reflexe zu entwickeln, einen kühlen Kopf und ein wachsames Auge zu bewahren...\n\nMan braucht Urteilsvermögen, Grips und Reife, um die Wildnis so schätzen zu können, wie ich es tue.\n\nAlso, worüber wollte ich eigentlich sprechen?\n\nAch ja, Probleme. Sprecht mit Donova Snowden bei den Thermalquellen. Sie wird Euch mehr sagen können.", objectives = "Findet Donova Snowden bei den Thermalquellen in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6604] = { title = "Wütende Wildekin", description = "Ist Euch das verlassene Lager südlich von hier aufgefallen? Es scheint, als wären die Wildekin verrückt geworden und haben so gut wie alles zerstört, was sie finden konnten!\n\nIch hab Gerüchte gehört, wonach einer der Überlebenden des Angriffs sich in Starfall aufhalten soll, das liegt westlich von hier. Ich bin neugierig, was wohl geschehen sein mag ... Ihr nicht auch?", objectives = "Sprecht mit Jaron Stoneshaper in Starfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6605] = { title = "Eine seltsame Person", description = "Ich bin gerade erst vom Teufelswald zurückgekehrt, $n. Unterwegs habe ich im Blutgiftposten Halt gemacht und eine wirklich eigenartige Bekanntschaft gemacht... Sie schien ganz besessen von einer Sache gewesen zu sein, und ich könnte Euch wohl erzählen, um was es sich handelt, aber ich denke, das sollte sie Euch selbst erklären.\n\nGeht zum Blutgiftposten im Westen des Teufelswalds und fragt nach Winna Hazzard, falls Ihr Interesse habt.\n\nWer weiß, vielleicht braucht sie ja Eure Hilfe...", objectives = "Sprecht im Teufelswald mit Winna Hazzard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6606] = { title = "Ein bisschen Glück", description = "Ein bisschen Glück kann man immer gebrauchen, nicht wahr? Ein kleiner Vorteil ist alles, was man braucht, um eine günstige Wendung herbeizuführen...\n\nIch habe vor einiger Zeit eine ziemlich exzentrische Hexendoktorin kennen gelernt. Sie fertigte einen Glücksbringer für mich... nicht gerade billig. Aber ich sage Euch, er war es auch wert!\n\nMöchtet Ihr vielleicht selbst gern einen haben? Sucht Hexendoktorin Mau'ari in Everlook auf. Meinen bekommt Ihr nämlich nicht!", objectives = "Sprecht in Everlook mit Hexendoktorin Mau'ari.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6607] = { title = "Nat Pagle, Extremangler", description = "Ich kann nicht behaupten, dass ich gern angele. Ich glaub, ich mach das jetzt seit gut 20 oder 30 Jahren.\n\nEs gibt wohl viele Gründe, die einen dazu treiben, etwas zu tun.\n\nIch will damit jetzt nicht sagen, dass Ihr 30 Jahre lang angeln oder jeden einzelnen Fisch im Meer fangen müsst, um ein Meisterangler zu werden. Man muss einfach nur entschlossen sein - entschlossen genug, um stundenlang auf dem Hintern zu sitzen und nichts zu tun.\n\nIch sag Euch was: Fangt mir ein paar seltene Fische, dann bring ich Euch das eine oder andere bei. Hier habt Ihr eine Liste:", objectives = "Nat Pagle möchte, dass Ihr folgende Fische fangt:\n\nNebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends.\n\nEinen Sar'theris-Barsch vom Sar'theris-Strand in Desolace.\n\nFeralas-Ahi aus dem Verdantis in Feralas.\n\nBlauwimpel von der ungezähmten Küste im Schlingendorntal.\n\nKehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6608] = { title = "Ihr zu gut", description = "Lumak können $N nix mehr beibringen. Ihr zu gut! Finden Freund von Lumak, Nat Pagle. Er sein Mensch, aber nix Futter! Ist Freund von Lumak! Nat Euch zeigen, wie besserer angeln.\n\nIhr finden Nat in Marschen von Dustwallow, Süden von Thermoro-odersoähnlich. Nat bestimmt angeln. Ihr jetzt gehen!", objectives = "Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6609] = { title = "Ich hab nix mehr!", description = "Ich bin ein Zwerg, zum Donnerwetter nochmal, $g Jungchen:junge Dame;! Ich hab mit Angeln nichts am Hut! Ich meine, seht mich doch mal an! Ich bestehe doch praktisch ganz aus Stein.\n\nIch hab nichts mehr - Ihr habt mich ausgelaugt. Ich hab Euch alles beigebracht, was ich weiß, flipflop!\n\nKapiert Ihr's nicht? Ah, gut. Ich hab in Kalimdor einen alten Freund, der Euch weiterhelfen kann. Heißt Nat Pagle, guter Junge. Findet ihn auf den Inseln südlich von Theramore. Jetzt verfatzt Euch!", objectives = "Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6610] = { title = "Muschelette Surprise", description = "Schon mal von einem Muschelette gehört? Natürlich nicht! Das ist mein neuestes kulinarisches Meisterwerk. Oh, $n, mir läuft das Wasser im Mund zusammen, wenn ich nur an ein Muschelette denke.\n\nLeider habe ich nichts mehr hier, um eins zu machen! Wie wär's mit einem Handel? Ihr besorgt die Zutaten für ein Muschelette und ich bring Euch die Feinheiten der exotischen Küche bei und leg' sogar noch ein paar Muschelettes drauf! Abgemacht?\n\nUnd das brauche ich dafür:", objectives = "Dirge Quikcleave möchte, dass Ihr folgende Dinge besorgt:\n\n12 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten.\n\n10 Stück scharfes Muschelfleisch. Die findet Ihr natürlich in Muscheln!\n\n20 Stück Alteraclochkäse. Begebt Euch zu einer Käserei!\n\nSammelt all diese Gegenstände und kehrt dann zu Dirge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6611] = { title = "Ab mit Euch nach Gadgetzan!", description = "Erwartet Ihr etwa, dass Zamja Euch noch irgendwas beibringt? Ihr kennt schon alle von Zamjas Küchentricks und verlangt immer noch nach mehr!\n\nZamja kann nicht helfen. Fetter $R muss nach Gadgetzan gehen. Dort findet Ihr einen kleinen Goblin namens Dirge - er wird Euch helfen, Dickerchen.\n\nWenn Ihr dann ein richtiger Sternekoch seid, kommt Ihr zurück und gebt Zamja Unterricht, okay? Und jetzt geht!", objectives = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6612] = { title = "Ich kenne einen Typen...", description = "Das seh ich doch an Eurem Kochlöffel, dass Ihr wisst, was Ihr tut. Leider kann ich Euch nichts beibringen.\n\nGlück für Euch, ich kenn da einen Typen. Er ist ein Goblin und wahrscheinlich der beste Koch von ganz Kalimdor.\n\nHajo, und jetzt die schlechte Nachricht, $g Jungchen:Mädel; - Ihr müsst nach Kalimdor reisen. Geht nach Gadgetzan und sucht nach Dirge Quikcleave. Er wird's Euch beibiegen.", objectives = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6621] = { title = "König der Fäulnisklauen", description = "$N, südöstlich von Astranaar lebt noch ein anderer Stamm Furbolgs, die Fäulnisklauen. Es gibt zwar nicht so viele von ihnen wie das bei den Distelfellen der Fall ist, aber ihre Wildheit könnte sich in der Zukunft zu einem Problem auswachsen. Wir könnten diese Bedrohung durch eine Demonstration der Macht beseitigen.\n\nNehmt dieses Banner, geht ins Dorf der Fäulnisklauen und platziert es auf ihrem Totemhügel. Sie werden versuchen, das Banner zu zerstören, aber Ihr müsst Eure Stellung halten, bis ihr Häuptling Murgut auftaucht, um das Gesicht seines Stammes zu wahren. Bringt mir das Totem, das er trägt.\n\nVersammelt Eure Verbündeten, $N. Dies ist keine Aufgabe für einen einzelnen $C.", objectives = "Platziert Karangs Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Karang Amakkar in Zoram'gar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6622] = { title = "Triage", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Horde.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die einfach Verletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nVerbände werden gestellt.\n\nViel Glück, Doktor.", objectives = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6623] = { title = "Traumachirurg der Horde", description = "Doktor $n, nehme ich an. Es ist mir eine Freude, Euch wiederzusehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Doktor Gregory Victor, Chefarzt der Traumachirurgen der Horde, hat Euch persönlich angefordert, damit Ihr Euch ihm in Hammerfall anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gregory Victor studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen!", objectives = "Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6624] = { title = "Triage", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Allianz.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die einfach Verletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nViel Glück, Doktor.", objectives = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6625] = { title = "Traumachirurg der Allianz", description = "Doktor $N, nehme ich an. Es ist mir eine Freude, Euch zu sehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Gustaf van Howzen, Chefarzt der Traumachirurgen der Allianz, hat Euch persönlich angefordert, damit Ihr Euch ihm in Theramore anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gustav van Howzen studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen, Doktor!", objectives = "Reist nach Theramore in den Marschen von Dustwallow und sprecht mit Doktor Gustaf van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6626] = { title = "Ein Hort des Bösen", description = "Die Verlassenen geben ihre... Krankheit... nicht weiter, soweit ich das sehe. Dieser Diplomat scheint Untote als Möchtegernanhänger zu betrachten. Ich glaube langsam, dass er der Geißel angehört.\n\nUm ihn mache ich mir allerdings momentan keine Gedanken, sondern um die wachsende Schar um ihn herum. Tag für Tag kriechen sie aus den Schatten und betteln ihn nahezu um mehr Macht an.\n\nIch bin nicht stark genug, um sie allein zu bekämpfen, $n. Was meint Ihr? Hättet Ihr Lust, auf die Jagd zu gehen?", objectives = "Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6627] = { title = "Test der Lehre", description = "Ihr habt mir das Buch gebracht, und jetzt ist es an der Zeit für Eure Befragung. Seid Ihr bereit?\n\nZeit spielt keine Rolle, $C, also fühlt Euch nicht unter Druck gesetzt. Ihr könnt Euch mit der Antwort so viel Zeit lassen, wie Ihr möchtet.", objectives = "Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6628] = { title = "Test der Lehre", description = "Die Zeit ist also wieder einmal gegen uns. Für einen Studenten der Lehre habt Ihr große Hartnäckigkeit bewiesen, indem Ihr meine Aufgabe erledigt habt.\n\nUnd deshalb werde ich Euch eine Frage anbieten. Wenn Ihr bereit seid, sprecht mich wieder an, und lasst Euch so viel Zeit, wie Ihr braucht, $n - es besteht keine Notwendigkeit, schnell zu antworten.", objectives = "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Undercity sein, wenn Ihr bereit seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6629] = { title = "Tötet Grundig Finsterwolke", description = "$n, Ihr habt gute Arbeit geleistet, indem Ihr Grimmtotem tötetet. Grundig Finsterwolke und seine persönliche Schlägerbande sind bei weitem die Schlimmsten von allen, wenn Ihr Euch traut. Er war einer derjenigen, die den brutalen Angriff auf mein Dorf anführten.\n\nIhr findet ihn im Grimmtotemposten ein Stück weiter den Weg nach Westen hinauf. Tötet ihn, dann werde ich Euch immer dankbar sein.", objectives = "Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6641] = { title = "Vorsha die Peitscherin", description = "Vorsha die Peitscherin... die satanische Hydra, die die Meere durchstreift...\n\nSie hat unseren Außenposten angegriffen, völlig ohne Grund, und dabei alles verheert, was auf ihrem Weg lag.\n\nAber ich bin bereit, $n. Ich bin bereit, die Hydra zu besiegen und den Angriffen auf Zoram'gar ein Ende zu setzen.\n\nDie Naga verehren die tückische Natur dieser Bestie mit einer Kohlenpfanne, die auf einer Insel gleich vor der Küste immer am Brennen gehalten wird. Ich denke, dass Vorsha erzürnt auftauchen wird, wenn wir sie löschen.\n\nWir werden jedoch Hilfe brauchen, also solltet Ihr ein paar starke Verbündete mitbringen.", objectives = "Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft.\n\nWenn Ihr erfolgreich gewesen seid, kehrt zum Zoram'garposten zurück und informiert den Warsongläufer über den Tod von Vorsha der Peitscherin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6642] = { title = "Gunst der Bruderschaft, Dunkeleisenerz", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6643] = { title = "Gunst der Bruderschaft, Feuerkern", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6644] = { title = "Gunst der Bruderschaft, Lavakern", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6645] = { title = "Gunst der Bruderschaft, Kernhäute", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6646] = { title = "Gunst der Bruderschaft, Blut des Berges", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6661] = { title = "Tiefenbahn-Ratten-Razzia", description = "Haltet ein, Taugenichts. Arrrr... Sucht Ihr Arbeit? Wir ha'm hier ein echtes Rattenproblem und nicht genügend Leute auf dem Hüttendeck.\n\nWas sagt Ihr? Ihr müsst nur diese Rattenfängerflöte nehmen und dem Ungeziefer ein Liedchen vorspielen. Die folgen Euch dann bis ans Ende der Welt!\n\nFangt mir fünf von den kleinen Mistviechern und bringt sie mir. Ich brauch sie lebendig.\n\nArrrrr...", objectives = "Fangt mit Hilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty. Und vergesst nicht, die Flöte zurückzugeben, wenn Ihr fertig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6662] = { title = "Mein Bruder Nipsy...", description = "Mein Bruder Nipsy hat 'n Rattengeschäft auf der anderen Seite der Tiefenbahn. Ihr müsst die Kiste mit Ratten hier zu ihm bringen, bevor sie schlecht werden. Zackig!\n\nIhr seid doch wohl schon mal mit 'ner Bahn gefahren, oder? Ganz einfach. Steigt einfach ein, wenn sie kommt, und genießt die Fahrt. Und haltet Eure Arme und Beine während der Fahrt drinnen, wenn Ihr keine Holzgräten haben wollt.", objectives = "Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6681] = { title = "Das Anwesen, Ravenholdt", description = "$N,\n\nRavenholdt interessiert sich für Euch, junger Dieb. Wir haben Euch beobachtet. Euer Stil ist ein bisschen unbeholfen, aber daran können wir arbeiten.\n\nWenn Ihr bereit seid, eine Karriere als Schüler von Meister Ravenholdt in Angriff zu nehmen und Mitglied der Auftragsmörderliga zu werden, müsst Ihr nur das Ravenholdt-Siegel (diesem Brief beigefügt) zum Ravenholdt-Anwesen bringen.\n\nEure erste Aufgabe ist es, das Anwesen zu finden, das versteckt in den Hügeln von Hillsbrad liegt, um Eure Schlauheit zu demonstrieren.\n\nHochachtungsvoll,\n\nFahrad", objectives = "Bringt das Ravenholdt-Siegel zu Fahrad im Ravenholdt-Anwesen, das versteckt in den Hügeln von Hillsbrad liegt.\n\nUnterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6701] = { title = "Syndikatsembleme", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6721] = { title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6722] = { title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6741] = { title = "Mehr Beute!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6761] = { title = "Die neue Grenze", description = "Ich habe meinen Stellvertreter Mathrengyl Bearwalker beauftragt, sich um Moonglades Bitte um Unterstützung zu kümmern. Sprecht mit ihm über diese Angelegenheit - NICHT mit mir.\n\nLasst mich Euch einen... gut gemeinten... Rat geben. ICH habe uns aus der Dunkelheit geführt - NICHT der Zirkel des Cenarius in Moonglade -, als für unser Volk alles verloren war. Teldrassil gibt uns allen neues Leben! Sie wollen Euch anderes glauben machen, und ihre Propaganda zu glauben, wäre reine Blauäugigkeit.\n\nIch werde es Euch überlassen, ob Ihr ein Narr sein wollt oder nicht.", objectives = "Sprecht mit Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6762] = { title = "Rabine Saturna", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos in Moonglade Unterstützung bei der Erforschung des riesigen Ödlandes weit im Westen von Tanaris... und noch weiter im Westen von Un'Goro. Ihr solltet ihn in Nighthaven finden, dem Hauptort von Moonglade.\n\nEure Arbeit wird zwar zweifellos sehr vorteilhaft für uns sein, dennoch rate ich Euch, Vorsicht walten zu lassen. Es gibt Spannungen zwischen Darnassus und Moonglade... Spannungen, die im Laufe der Zeit wachsen könnten.", objectives = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6781] = { title = "Mehr Rüstungsfetzen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6801] = { title = "Lokholar der Eislord", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6804] = { title = "Vergiftetes Wasser", description = "Eine Truppe von Elementarspähern wurde in die Östlichen Pestländer von Lordaeron entsandt und die Krankheit dieses Orts verdrehte und infizierte sie. Die Wasserlords können diese Beleidigung unserer Reinheit nicht dulden!\n\nNehmt diese Phiole. Darin befindet sich ein Quäntchen eines Aspekts von Neptulon. Wenn das auf die verseuchten Elementare angewendet wird, bekämpft es das Gift in ihren Körpern und heilt sie! Ihr innerer Konflikt wird sie allerdings in den lodernden Wahnsinn treiben.\n\nBesiegt die disharmonischen Wogen und bringt mir ihre Armschienen der Bindung.", objectives = "Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6805] = { title = "Stürmer und Rumpler", description = "Wir, die Elementare des Wassers, führen Krieg mit den Wesen der niederen Elemente. Wenn Ihr in diesem Konflikt wirklich unser Verbündeter seid, dann beweist mir Eure Überzeugung!\n\nWeit im Süden, im Wüstenland Silithus, treiben sich die Diener der Luft und Erde in einer Felsenecke herum, die Kristalltal genannt wird. Sie schützen Gegenstände der Macht vor kleineren Wesen und Sterblichen, und obwohl ich nicht weiß, warum sie das tun, will ich ihre Bemühungen zunichte machen.\n\nBegebt Euch zum Kristalltal in Silithus und besiegt unsere Feinde. Kehrt danach zu mir zurück.", objectives = "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6821] = { title = "Auge des Glutsehers", description = "Ihr habt mir gezeigt, dass Ihr unsere Feinde besiegen und Missionen ausführen könnt, um die Sache der Wasserlords weiter voranzutreiben. Aber bisher seid Ihr nur niederen Feinden gegenübergetreten... wenn Ihr gegen einen mächtigen Feind geschickt werdet, könnt Ihr dann siegen?\n\nDas ist Eure neue Aufgabe.\n\nHoch droben auf der Blackrockspitze haben die Orcs einen Diener des Feuers gefangen genommen, die Feuerwache Glutseher. Sucht den Ort seiner Gefangenschaft, erschlagt seine Häscher und erschlagt dann den Glutseher. Bringt mir sein Auge. Das wird mir Euren Wert zeigen.", objectives = "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6822] = { title = "Der Geschmolzene Kern", description = "$N, vielleicht ist es jetzt an der Zeit, Euch einem echten Test zu unterziehen. Seid Ihr bereit?\n\nAm Fuß der Blackrocktiefen befindet sich ein Durchgang zum geschmolzenen Kern. Er ist eine Festung unseres Feindes, in der Hand des mächtigsten Dieners des Feuers in dieser Welt.\n\nBegebt Euch zum geschmolzenen Kern, $N. Zeigt mir, dass Ihr über die Kraft und den Willen verfügt, das zu besiegen, was Ihr dort finden werdet.\n\nUnd wenn Ihr Verbündete in Eurem Volk habt, dann versammelt sie. Nichts Geringeres als eine Armee kann hoffen, den geschmolzenen Kern zu betreten und zu überleben.", objectives = "Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6823] = { title = "Agent von Hydraxis", description = "Wenn Ihr wirklich ein Bündnis mit uns wünscht, dann schlage ich vor, dass Ihr Krieg gegen unsere Feinde führt, die Diener von Luft und Erde und Feuer. Jede Niederlage, die Ihr ihnen beibringt, wird ihren Stand hier schwächen und Eure Verbindung zu unserer Sache weiter untermauern.\n\nVor Euch liegen lange und harte Schlachten, doch wenn Ihr diese übersteht, so winken Euch Ruhm und Ehre.", objectives = "Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6824] = { title = "Hände des Feindes", description = "$N, Euer Dienst ist für uns von großem Wert, und daher zögern wir, Euch auf diese letzte Mission zu schicken, denn wir wollen einen solch nützlichen Agenten nicht verlieren.\n\nAber der Erfolg würde unsere Kriegsbemühungen ungeheuer voranbringen und... das wird als ausreichend erachtet, Euer Leben zu riskieren.\n\nWir wollen, dass diese Captains im geschmolzenen Kern vernichtet werden: Lucifron, Sulfuron, Gehennas und Shazzrah. Tötet sie und bringt mir ihre Hände!\n\nDiese Aufgabe wird Euer ganzes Können erfordern, $N, aber wenn Ihr erfolgreich seid, dann wird den Feuerlords ein schrecklicher Schlag versetzt.", objectives = "Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
