quests[7507] = { title = "Forors Kompendium", description = "Ihr habt etwas von größter Wichtigkeit entdeckt. Dieses Buch ist anders, als alle anderen die Ihr bisher gesehen habt.\n\nEs scheint, als hätte jemand oder etwas es geschafft, das Siegel des Athenaeums aufzubrechen. Der Text in seinem Inneren ist beschädigt und schwer lesbar.", objectives = "Bringt Forors Kompendium des Drachentötens zurück in das Athenaeum.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7508] = { title = "Das Schmieden von Quel'Serrar", description = "Wenn Ihr diese Aufgabe annehmen wollt, zeigt Lydros die glanzlose Klinge.", objectives = "Bringt dem Wissenshüter Lydros die stumpfe und glanzlose Elfenklinge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7509] = { title = "Das Schmieden von Quel'Serrar", description = "Bringt das uralte, noch unerhitzte Schwert in Onyxias Hort und tretet ihr im Kampf gegenüber.\n\nNur mit einem Trick werdet Ihr es schaffen die Klinge zu erhitzen, also hört gut zu. Im Kampf wird Sie mit Sicherheit nichts unversucht lassen, um Euch mit ihrem Feueratem einzuäschern. Legt die Klinge irgendwo in der Nähe von Onyxia ab und hofft, dass ihr feuriger Atem diese Klinge erhitzt. Sollte es klappen und Ihr noch am Leben sein, hebt die dann erhitzte uralte Klinge wieder auf und erledigt den Drachen.\n\nRammt anschließend die noch heiße Klinge in den schwelenden Drachenkörper, um dadurch eine behandelte uralte Klinge zu erhalten.", objectives = "Bringt Onyxia dazu, ihren Feueratem auf die noch unerhitzte Klinge zu benutzen. Sobald dies geschehen ist, hebt die erhitzte Klinge wieder auf. Doch seid gewarnt, die erhitzte Klinge wird nicht auf ewig erhitzt bleiben - behaltet also die Zeit im Auge.\n\nZuletzt müsst Ihr das Biest töten und die uralte erhitzte Klinge in ihren Leib rammen. Kehrt anschließend zu mir zurück und Quel'Serrar wird Euer sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7541] = { title = "Dienst an der Horde", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7562] = { title = "Mor'zul Blutbringer", description = "$n, Eure Studien der dunklen Künste sind sehr eingehend. Euer Einfluss auf die Kräfte der jenseitigen Welt ist sehr stark geworden... ich denke, Ihr seid nun bereit eines der berüchtigten Schreckensrösser an Euch zu binden.\n\nDas Ritual zum Beschwören eines dieser Biester erfordert große Macht und Ressourcen, doch wenn Ihr solch ein episches Reittier beherrschen wollt, sprecht mit Meister Mor'zul Blutbringer. Er hat sein Lager nahe des Altars der Stürme in der Brennenden Steppe aufgeschlagen.\n\nGeht, $n. Diese Aufgabe wird sehr gefährlich werden, aber ein Hexenmeister von Eurer Statur sollte sich nicht vor Gefahr fürchten.", objectives = "Sprecht mit Mor'zul Blutbringer beim Altar der Stürme in der Brennenden Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7563] = { title = "Kochendes Blut", description = "Die Schreckensrösser existieren auf einer uns fremden Welt, in der feurigen Ebene von Xoroth. Um eines dieser einzigartigen Tiere an Euch zu binden, werdet Ihr mächtige Glyphen beschwören müssen. Ich werde für Euch die erforderlichen Glyphen auf einem Pergament niederschreiben, doch dafür brauche ich eine ganz spezielle Tinte.\n\nIm weit entfernten Winterquell lebt eine besondere Eulenart. Einst waren es normale Tiere, doch die dämonische Macht der Flüsternden Schlucht trieb sie in den Wahnsinn. Übrig blieben nur Blutrünstige Bestien.\n\nEs ist ihr Blut, das ich zum Zeichnen der Glyphen benötige. Bringt mir etwas davon und ich kann Euch weiterhelfen.", objectives = "Mor'zul Blutbringer in der Brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7564] = { title = "Wildaug", description = "Mein Assistent Gorzeeki ist ein recht bewanderter Alchemist. Er sollte in der Lage sein die Tinte herzustellen, die ich für die Herstellung der Schriftrolle benötige. Ich habe das von Euch mitgebrachte Blut destilliert. Nehmt es und bringt es zu Gorzeeki, damit er mit seiner Arbeit beginnen kann.", objectives = "Bringt den Behälter mit Blut zu Gorzeeki Wildaug beim Altar der Stürme in der Brennenden Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7581] = { title = "Das Fundament des Gefängnisses", description = "Ihr müsst ein geeignetes Fundament für das Gefängnis der Verdammniswache finden.\n\nDas Blut der Wildhufsatyrn, die in Düsterbruch hausen, sollte dem Genüge tun. Das geronnene Blut wird die Splitter von Hederine zusammenhalten und das Kristallgefängnis mit Energie versorgen.", objectives = "Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der Faulenden Narbe zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7582] = { title = "Die Gefängnishülle", description = "Die Dämonen von Hederine, die das Vorgebirge des Berges Hyjal bevölkern, sondern mächtige Gifte ab, die mit der Zeit hart und somit zu einem kompakten Anti-Magiekristall werden. Diese Kristalle sind auch als Tränen der Hederine bekannt.\n\nNicht einmal die gewaltige Macht einer Verdammniswache könnte die Wände eines Gefängnisses durchbrechen, die aus diesem Material errichtet wurden.\n\nReist in die flüsternde Schlucht in Winterspring und holt Euch die Tränen.", objectives = "Reist in die flüsternde Schlucht in Winterspring und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7583] = { title = "Unterdrückung", description = "Das Gefängnis ist bereit. Jetzt kommen wir zum schwierigsten Teil des Unterfangens.\n\nIhr müsst mithilfe des Kristallgefängnisses einen Verdammniswachenkommandanten in der Faulenden Narbe finden und fangen.\n\nSeid gewarnt! Verdammniswachen sind gerissene und tödliche Gegner, die Euch sofort zu zerstören versuchen werden, sobald Ihr mit dem Ritual der Gefangenschaft beginnt. Euer Gegner wird bei seinem Versuch der Gefangenschaft zu entgehen nichts unversucht lassen.\n\nEr wird sich nur auf Euch konzentrieren, $n. Ich muss Euch deshalb zu der Begleitung von einigen Gefährten raten, die fähig genug sind, um Euch am Leben zu erhalten!", objectives = "Wagt Euch in die Faulende Narbe heraus und macht einen Verdammniswachenkommandanten ausfindig.\n\nWendet das leuchtende Kristallgefängnis auf den Verdammniswachenkommandanten an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird.\n\nSolltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der Faulenden Narbe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7601] = { title = "Nibys Anweisungen", description = "Wenn ich Euch das Geheimnis der Beschwörung eines Höllenbestiendieners lehren soll, so müsst Ihr Kroshius zerstören und mir den Höllenbestienkern seiner brennenden Überreste bringen. Wie auch immer, es ist nicht so einfach wie es klingt. Kroshius hat zwar alles, ist aber vollständig ausgebrannt. Ihr müsst seinen Körper wieder entzünden und ihn wieder von dem Schutthaufen auferstehen lassen. Allerdings braucht Ihr dafür ein paar Komponenten von anderen Dämonenwesen.\n\nImpsy, mein Wichtel, soll Euch auf alles weitere vorbereiten.", objectives = "Sprecht mit Impsy im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7602] = { title = "Reine Teufelsessenz", description = "Ihr werdet für die Wiederbelebung von Kroshius Teufelsfeuer benötigen. Ich kann zwar Teufelsfeuer machen, brauche dazu aber ein paar Komponenten.\n\nIhr müsst mir reine Teufelsessenz aus drei bestimmten Gebieten der Welt bringen.\n\nDen ersten Essenztyp findet Ihr bei den Satyrn der Legashi von Azshara; den zweiten Typ bei den Legionären von Jaedenar in Jaedenar und den dritten bei den Wachposten der Teufelswache in den Verwüsteten Landen.\n\nBringt mir jeweils eine Essenz pro Typ, dann werde ich das Teufelsfeuer entfachen, mit dem Ihr Kroshius wieder auferstehen lassen könnt.", objectives = "Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.\n\nDie Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den Verwüsteten Landen bergen die Teufelsessenz ihrer Region.\n\nFindet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7603] = { title = "Kroshius Höllenbestienkern", description = "Kroshius liegt zusammengefallen im Shatter Scar-Tal, Richtung Nordosten. Verwendet dieses Teufelsfeuer auf seinen Überresten, es sollte die gefallene Höllenbestie wieder erwecken.\n\nIch bin überzeugt, dass er Euch und Eure eventuell mitgebrachten Begleiter genau dann umbringen wird - und glaubt mir, Ihr werdet ein paar Freunde bei Euch haben wollen.\n\nSolltet Ihr Kroshius dennoch auf wundersame Weise töten können, dann nehmt den Höllenbestienkern und bringt ihn zu Niby.", objectives = "Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.\n\nBringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7604] = { title = "Ein verbindlicher Vertrag", description = "$g Der Unterzeichner:Die Unterzeichnerin; erklärt hiermit, dass es sich bei dem Sulfuronblock, der an die Thoriumbruderschaft (TB Ltd.) geliefert wird, um ein Original und nicht um eine Nachbildung handelt. $g Der Unterzeichner:Die Unterzeichnerin; erkennt ebenso an, dass jeglicher Schaden, der $g ihm:ihr; in Folge des Versuchs Sulfuras herzustellen, zu schmieden, verkaufen oder zu essen widerfahren könnte, nicht in der Verantwortung oder Verschuldung von TB Ltd. liegt.\n\nMit Unterzeichnung dieses Vetrags, wird allen darin aufgelisteten Bedingungen zugestimmt.\n\n_________________\n\nUnterschrift", objectives = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Darkbargainer, wenn Ihr die Pläne für das Sulfuron erhalten möchtet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7621] = { title = "Eine Warnung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7622] = { title = "Die Waage von Licht und Schatten", description = "Ihr müsst tun was ich nicht konnte: Rettet die Arbeiter, die während ihrer Flucht von Stratholme niedergemäht wurden.\n\nSie werden dem Licht entgegen laufen, sorgt für ihr Überleben. Sollten zu viele von ihnen fallen, wird unsere Existenz auch weiterhin verdammt sein - und Ihr werdet versagt haben.\n\nAlle von Euch gelernten Fähigkeiten, Gebete und Zauber werden auf die Probe gestellt werden. Möge das Licht Euch beschützen, $n.", objectives = "Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Havenfire, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.\n\nKonsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7623] = { title = "Lord Schattenfluch", description = "Mor'zul sagte mir, dass Ihr ein Portal nach Xoroth öffnen möchtet. Für eine solche Aufgabe werdet Ihr xorothianischen Sternstaub benötigen und der ist nur schwer in Azeroth zu finden!\n\nAber es gibt jemanden, der welchen besitzen sollte: Lord Schattenfluch in Jaedenar, dem Sitz des Schattenrats! Sprecht mit ihm und vielleicht wird er Euch etwas Sternenstaub überlassen.\n\nDoch wenn Ihr nach Jaedenar wollt, solltet Ihr Euch mit dem gleichen Aroma des Bösen, das den Schattenrat umgibt, tarnen. Dazu werdet Ihr einige meiner schattenhaften Tränke brauchen und die sind nicht umsonst...", objectives = "Erwerbt schattenhafte Tränke von Gorzeeki Wildaug beim Altar der Stürme in der Brennenden Steppe.\n\nBenutzt die Tränke um durch Jaedenar im Teufelswald zu reisen und sprecht mit Lord Schattenfluch in der Schattenfeste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7624] = { title = "Ulathek der Verräter", description = "Ihr wollt meine Gunst erlangen? Dann tötet für mich.\n\nMein Diener Ulathek treibt ein erbärmliches Spiel, während er wie ein elender Wurm vor mir kriecht, konspiriert er heimlich mit Lord Hel'nurath von Xoroth. Hel'nurath trachtet danach meine Macht an sich zu reißen und Ulathek ist sein Spion...\n\nBeweist mir, dass Ihr mir und nicht meinem Rivalen dient. Stellt Ulathek in seinem Quartier, der Schattenfeste im Osten. Macht ihm klar, dass ich sein kleines Geheimnis kenne und seht wie die Angst von ihm Besitz ergreift. Bringt mir anschließend das Herz des Verräters!", objectives = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Schattenfluch in Jaedenar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7625] = { title = "Xorothianischer Sternenstaub", description = "Ihr kommt also zu mir, weil Ihr xorothianischen Sternenstaub sucht? Ihr möchtet ein Portal nach Xoroth, dem Herrschaftsgebiet meines Rivalen Hel'nurath öffnen? Vielleicht plant Ihr sogar eines seiner geliebten Schreckensrösser zu stehlen?\n\nNun gut. Mein Diener Ur'dan hat einen Vorrat an Sternenstaub. Ihr könnt es von ihm bekommen... wenn ihr den Preis bezahlen könnt.", objectives = "Erwerbt xorothianischen Sternenstaub von Ur'dan tief im Inneren der Schattenfeste in Jaedenar im Teufelswald. Bringt es anschließend Gorzeeki Wildaug in der Brennenden Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7626] = { title = "Die Glocke von Dethmoora", description = "Um einen mächtigen Beschwörungskreis herzustellen, benötigt man eine Glocke von Dethmoora, benannt nach dem uralten Hexenmeister Dethmoora Finsteraugen. Richtig abgestimmt mit dem Rad und der Kerze, speichern diese Gegenstände riesige Mengen arkaner Macht.\n\nMein Assistent Gorzeeki kann eine solche Glocke herstellen, allerdings benötigt er dafür einen großen Vorrat an Elixieren der Schattenmacht. Besorgt Euch die Elixiere von einem Alchemisten und bringt sie Gorzeeki.", objectives = "Bringt 10 Elixiere der Schattenmacht zu Gorzeeki Wildaug in die Brennende Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7627] = { title = "Das Rad des Schwarzen Marsches", description = "Ein Rad des Schwarzen Marsches enthält und kontrolliert die gefährlichen Energien, welche für das Ritual des mächtigen Beschwörungskreises benötigt werden. Um das Rad zu konstruieren, benötigt Gozeeki große glänzende Splitter von einem Verzauberer und Dunkeleisen von einem Meisterbergmann.\n\nBeschafft diese Gegenstände und bringt sie meinem Assistenten.", objectives = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildaug in die Brennende Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7628] = { title = "Die Altarkerze des Jüngsten Gerichts", description = "Eine Altarkerze des Jüngsten Gerichts speichert Feuer in ihrem Inneren und schleudert es auf jeden, der versucht, Euer Ritual zu unterbrechen. Wenn Ihr das Ritual des mächtigen Beschwörungskreises aufbaut und die Kerze angezündet ist, wird sie jeden Dämon, der sich Euch in den Weg stellt, mit ihrer Flamme verbrennen.\n\nDieses spezielle Feuer einzufangen ist nicht einfach und erfordert die Essenz aus der Schuppe eines schwarzen Drachen. Beschafft Euch die Drachenschuppen und bringt sie zu Gorzeeki Wildaug.", objectives = "Bringt 35 Schuppen eines schwarzen Drachen zu Gorzeeki Wildaug in der Brennenden Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7629] = { title = "Wichtellieferung", description = "Es gibt noch eine Sache die für Mor'zuls Pergament erledigt werden muss. Ich benötige Papier, welches mit xorothianischem Sternenstaub versetzt ist. Leider kann ich diese Prozedur hier nicht durchführen, da mir die Ausrüstung dafür fehlt!\n\nIch kenne aber ein Alchemielabor mit der nötigen Ausstattung. Es befindet sich in Scholomance, auf der Insel Darrowehr in den Pestländern.\n\nIch kann diese Reise nicht selber machen, aber nehmt dieses Gefäß. Im Inneren befindet sich ein äußerst intelligenter Wichtel. Lasst ihn frei, wenn Ihr im Alchemielabor angekommen seid und er wird die Prozedur mit dem Sternenstaub für Euch vornehmen.", objectives = "Bringt den Wichtel im Glas in das Alchemielabor in Scholomance. Bringt das Glas nach der Herstellung des Pergaments zurück zu Gorzeeki Wildaug.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7630] = { title = "Arkanit", description = "Nachdem die Glocke, das Rad und die Kerze jetzt fertiggestellt sind, muss sie jemand auf das Ritual vorbereiten. Ich besitze einen Wichtel, der die Vorbereitungen genau kennt... Ihr braucht nur noch ein Behältnis, um ihn zu transportieren.\n\nIch kann Euch ein solches Behältnis verkaufen, aber um es herzustellen brauche ich Arkanit. Habt Ihr welches? Falls nicht, solltet Ihr einen Alchemisten finden, der es für Euch herstellen kann.\n\nKommt zu mir zurück, wenn Ihr das Arkanit habt, dann verkaufe ich Euch den Wichtel im Glas!", objectives = "Bringt 1 Arkanitbarren zu Gorzeeki in der Brennenden Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7631] = { title = "Schreckensross von Xoroth", description = "Alle Vorbereitungen sind getroffen. Als erstes müsst Ihr das Ritual des mächtigen Beschwörungskreises vollziehen. Anschließend benutzt die xorothianischen Glyphen um ein Portal nach Xoroth zu öffnen.\n\nIch habe Euch die Anweisungen für das Ritual auf eine Schriftrolle geschrieben. Studiert sie sorgfältig, denn wenn Ihr Erfolg haben wollt, müsst Ihr jeden Schritt exakt nach Anleitung durchführen.\n\nIch wünsche Euch viel Erfolg, $n. Und mögen die Seelen Eurer Feinde, den Weg in Euren Seelensteinbeutel finden.", objectives = "Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7632] = { title = "Das uralte Blatt", description = "Die Epidermis des Blatts leuchtet hellgrün. Die Oberfläche ist extrem runzelig und weist etliche Adern und Falten auf.\n\nMan könnte vermuten, dass dieses Blatt von etwas sehr Altem und Mächtigem stammt.\n\nVielleicht solltet Ihr den ursprünglichen Besitzer dieses Blatts ausfindig machen?", objectives = "Findet den Besitzer des uralten, versteinerten Blatts. Viel Glück, $n; die Welt ist groß.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7633] = { title = "Eine Einführung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7634] = { title = "Uraltes in Sehnen eingewickeltes Laminablatt", description = "Seid gegrüßt, $C. Ich bin Hastat der Uralte des Wissens. Ich bewahre seit Ewigkeiten verlorenes Wissen.\n\nRichtig gebunden kann eines meiner Blätter als Köcher dienen, dergleichen wurde seit 10.000 Jahren nicht mehr gesehen. Ein Köcher, der - wenn er von einem Bogen der Uralten begleitet wird - ungeahnte Kräfte verleihen könnte.\n\nKehrt mit der Sehne eines ausgewachsenen, blauen Drachens hierher zurück und der Köcher möge Euer sein.", objectives = "Hastat der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, blauen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Hastat im Teufelswald zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7635] = { title = "Die passende Sehne", description = "Vartrus wird Euch womöglich den Holzstab für die Erstellung eines Bogens der Uralten geben. Allerdings kann nur ich die benötigte Sehne verzaubern, die den Bogen vervollständigt.\n\nEs ist eine einfache Aufgabe, mickriges Geschöpf. Tötet einen ausgewachsenen, schwarzen Drachen und entfernt eine Sehne von seinen Knochen. Bringt mir diese Sehne und ich werde das Material in eine fast unzerstörbare Bogensehne verzaubern.", objectives = "Stoma der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, schwarzen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Stoma im Teufelswald zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7636] = { title = "Holzstab der Uralten", description = "Agenten der Brennenden Legion sind noch immer in unserer Welt aktiv, $C. Diese Agenten verderben alles, was ihnen unterkommt. Die Natur welkt und siecht in ihrer Gegenwart dahin.\n\nIhr müsst diese dämonischen Verderber aufspüren und zerstören, $n. Seid gewarnt, Ihr müsst sie selbst angreifen, andernfalls werden sie fliehen. Solange Ihr alleine seid, werden sie versuchen Euch zu zerstören. Ihr müsst sie bekämpfen und ihren Hochmut zu ihrem Verderben werden lassen.\n\nIch gewähre Euch ein Stück meiner Rinde, mögen die Inschriften Euch zu Eurem Ziel führen.", objectives = "Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören:\n\nSimone die Verführerin.\n\nKlinfran der Wahnsinnige.\n\nSolenor der Schlächter.\n\nArtorius der Verhängnisvolle.\n\nVernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück.\n\nHaltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten.\n\nIhr MÜSST diese Aufgabe eigenständig erledigen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7637] = { title = "Ein Opfer darbieten", description = "Um Euch auf diese Aufgabe vorzubereiten, müsst Ihr Eure Opferbereitschaft und Euer Urteilsvermögen beweisen... die Betonung liegt hier besonders auf 'opfern'.\n\nIhr benötigt Hohepriester Rohans Weihrauchschwenker für die kommende Aufgabe. Und obwohl Ihr damit gutes bewirken werdet, müsst Ihr etwas zum Ausgleich hergeben.\n\nBegebt Euch nach Eisenschmiede und sprecht dort mit dem Hohepriester. Nehmt reichlich Münzen mit, um ihm den Verlust seines Weihrauchschwenker zu vergelten und um Euren Opferwillen zu zeigen.\n\nGeht nun, $n, denn Zeit ist hier ein wichtiger Faktor.", objectives = "Reist nach Eisenschmiede und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7638] = { title = "Lord Grayson Schattenbruch", description = "$n, der Zeitpunkt ist nun gekommen, an dem Ihr lernen werdet, was Ihr tun müsst, um etwas zu bekommen, auf das Ihr bestimmt schon lange gewartet habt... Euer eigenes Streitross. Sprecht mit Lord Grayson Schattenbruch, hier im Kathedralenviertel von Sturmwind. Er wird Euch nicht nur in die Geheimnisse des treuesten Begleiters eines Paladins einweihen, sondern er wird Euch auch durch die Prüfungen führen, die Ihr absolvieren werdet, um Euer eigenes Streitross zu erhalten.\n\nIch wünsche Euch viel Glück mit dieser Prüfung. Für das Licht, $g nobler Bruder:noble Schwester;!", objectives = "Sprecht mit Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7639] = { title = "Lass Gerechtigkeit walten", description = "Nehmt diesen Weihrauchschwenker mit meinem Segen. Ich selbst habe ihn schon für dutzende Exzorzismen benutzt. Er wird Euch, bei den vor Euch liegenden Aufgaben, gut dienen.\n\nKehrt nun zu Lord Grayson Schattenbruch in Sturmwind zurück, $n. Ihr müsst Eure Suche mit seiner Hilfe fortsetzen.", objectives = "Bringt den Weihrauchschwenker zu Lord Grayson Schattenbruch in Sturmwind zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
